    MapTotalVATs(entityPM: APInvoicePM, jsonPM: any, mapParent: boolean = true) {

        var oldTotalVATs: APInvoiceTotalVATPM[] = [];
        if (entityPM.OldEntityPM && !mapParent) {
            oldTotalVATs = entityPM.OldEntityPM.TotalVATs;
        }

        entityPM.TotalVATs = new Array<APInvoiceTotalVATPM>();
        for (var item in jsonPM.TotalVATs) {
            var jItem = jsonPM.TotalVATs[item];
            if (mapParent && (jItem.ChangeSetOp == "Delete" || jItem.ChangeSetOp == 3)) {
                continue;
            }
            var newAPInvoiceTotalVATPM: APInvoiceTotalVATPM;
	  
            if (mapParent) {
                newAPInvoiceTotalVATPM = new APInvoiceTotalVATPM(entityPM);
            }
            else
            {
                newAPInvoiceTotalVATPM = new APInvoiceTotalVATPM(null);
            }
 			newAPInvoiceTotalVATPM.DisableMarkAsDirty = true;
               
            var pmKeysArray = Object.keys(jItem);
            for (var pmKey in pmKeysArray) {
                if ((!mapParent && pmKeysArray[pmKey] === "entityParentPM" )|| pmKeysArray[pmKey] === "UIProperties" || pmKeysArray[pmKey] === "PropertyChanged") {
                    continue;
                }
				                  var pmProperty = pmKeysArray[pmKey];
                newAPInvoiceTotalVATPM[pmProperty] = jItem[pmProperty];
            }
           
			 
            if (mapParent) {
                newAPInvoiceTotalVATPM.UniqueKey = Guid.newGuid();
                newAPInvoiceTotalVATPM.ChangeSetOp = "None";
                jItem.ChangeSetOp = "None";
                newAPInvoiceTotalVATPM.OldEntityPM = this.clone(newAPInvoiceTotalVATPM);

				
            }
            else {
                if (newAPInvoiceTotalVATPM.UniqueKey) {

                    if (jItem.IsDirty)
                        newAPInvoiceTotalVATPM.ChangeSetOp = "Update";
                }
                else {
                        newAPInvoiceTotalVATPM.ChangeSetOp = "Insert";
                }
 
                newAPInvoiceTotalVATPM.OldEntityPM = null;
                newAPInvoiceTotalVATPM.EntityParentPM = null;
            }
			 newAPInvoiceTotalVATPM.DisableMarkAsDirty = false;
			 newAPInvoiceTotalVATPM.IsDirty = false;
            entityPM.TotalVATs.push(newAPInvoiceTotalVATPM);
        }
        if (oldTotalVATs) {
            
            for (var itemKey in oldTotalVATs) {
                if (entityPM.TotalVATs.filter(p=> p.UniqueKey === oldTotalVATs[itemKey].UniqueKey).length === 0) {
				
                    if (oldTotalVATs[itemKey]) {
                        //oldTotalVATs[itemKey].ChangeSetOp = "Delete";
                        //entityPM.TotalVATs.push(oldTotalVATs[itemKey]);
						var oldItemJson = oldTotalVATs[itemKey];
                        var deletedPM: APInvoiceTotalVATPM = new APInvoiceTotalVATPM(null);
						deletedPM.DisableMarkAsDirty = true;
                        var pmKeys = Object.keys(oldItemJson);
                        for (var key in pmKeys) {

                            if ((!mapParent && pmKeys[key] === "entityParentPM") || pmKeys[key] === "UIProperties" || pmKeys[key] === "OldEntityPM" || pmKeys[key] === "PropertyChanged") {
                                continue;
                            }

                            var property = pmKeys[key];
                            deletedPM[property] = oldItemJson[property];
                        }

					    deletedPM.DisableMarkAsDirty = false;
                        deletedPM.IsDirty = false;
                        deletedPM.ChangeSetOp = "Delete";
                        
                        deletedPM.OldEntityPM = null;
                        entityPM.TotalVATs.push(deletedPM);
                    }
                }
            }
        }
    }

	  public clone(jsonPM: any) {
        var entityPM: any;
        entityPM = {};

        var jsonPMKeys = Object.keys(jsonPM);
        for (var key in jsonPMKeys) {
            
            if ((jsonPMKeys[key] === "entityParentPM") || jsonPMKeys[key] === "UIProperties" || jsonPMKeys[key] === "OldEntityPM" || jsonPMKeys[key] === "PropertyChanged") {
                continue;
            }

            var property = jsonPMKeys[key];
            entityPM[property] = jsonPM[property];

        }
        return entityPM;
    }

